@Test
public void createEvaluationContextSupplierAuthentication() {
    setupMocks();
    Supplier<Authentication> mockAuthenticationSupplier = mock(Supplier.class);
    given(mockAuthenticationSupplier.get()).willReturn(this.authentication);
    EvaluationContext context = this.handler.createEvaluationContext(mockAuthenticationSupplier, this.methodInvocation);
    verifyNoInteractions(mockAuthenticationSupplier);
    assertThat(context.getRootObject()).extracting(TypedValue::getValue).asInstanceOf(InstanceOfAssertFactories.type(MethodSecurityExpressionRoot.class)).extracting(SecurityExpressionRoot::getAuthentication).isEqualTo(this.authentication);
    verify(mockAuthenticationSupplier).get();
}

