@Test
void requestWhenUnauthenticatedThenRequiresTwoSteps() throws Exception {
    this.spring.register(MfaDslConfig.class, UserConfig.class).autowire();
    UserDetails user = PasswordEncodedUser.user();
    this.mockMvc.perform(get("/profile").with(user(user))).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("http://localhost/login?factor.type=password&factor.type=ott&factor.reason=missing&factor.reason=missing"));
    this.mockMvc.perform(post("/ott/generate").param("username", "rod").with(user(user)).with(SecurityMockMvcRequestPostProcessors.csrf())).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("/ott/sent"));
    this.mockMvc.perform(post("/login").param("username", "rod").param("password", "password").with(SecurityMockMvcRequestPostProcessors.csrf())).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("/"));
    user = PasswordEncodedUser.withUserDetails(user).authorities("profile:read", FactorGrantedAuthority.OTT_AUTHORITY).build();
    this.mockMvc.perform(get("/profile").with(user(user))).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("http://localhost/login?factor.type=password&factor.reason=missing"));
    user = PasswordEncodedUser.withUserDetails(user).authorities("profile:read", FactorGrantedAuthority.PASSWORD_AUTHORITY).build();
    this.mockMvc.perform(get("/profile").with(user(user))).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("http://localhost/login?factor.type=ott&factor.reason=missing"));
    user = PasswordEncodedUser.withUserDetails(user).authorities("profile:read", FactorGrantedAuthority.PASSWORD_AUTHORITY, FactorGrantedAuthority.OTT_AUTHORITY).build();
    this.mockMvc.perform(get("/profile").with(user(user))).andExpect(status().isNotFound());
}

@Test
void requestWhenUnauthenticatedX509ThenRequiresTwoSteps() throws Exception {
    this.spring.register(MfaDslX509Config.class, UserConfig.class, BasicMfaController.class).autowire();
    this.mockMvc.perform(get("/profile")).andExpect(status().is3xxRedirection());
    this.mockMvc.perform(get("/profile").with(user(User.withUsername("rod").authorities("profile:read").build()))).andExpect(status().isForbidden());
    this.mockMvc.perform(get("/login")).andExpect(status().isOk());
    this.mockMvc.perform(get("/profile").with(SecurityMockMvcRequestPostProcessors.x509("rod.cer"))).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("http://localhost/login?factor.type=password&factor.reason=missing"));
    this.mockMvc.perform(post("/login").param("username", "rod").param("password", "password").with(SecurityMockMvcRequestPostProcessors.x509("rod.cer")).with(SecurityMockMvcRequestPostProcessors.csrf())).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("/"));
    UserDetails authorized = PasswordEncodedUser.withUsername("rod").authorities("profile:read", FactorGrantedAuthority.X509_AUTHORITY, FactorGrantedAuthority.PASSWORD_AUTHORITY).build();
    this.mockMvc.perform(get("/profile").with(user(authorized))).andExpect(status().isOk());
}

