@Test
public void requestWhenTokenEndpointCustomizedThenUsed() throws Exception {
    this.spring.register(AuthorizationServerConfigurationCustomTokenEndpoint.class).autowire();
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient2().build();
    this.registeredClientRepository.save(registeredClient);
    OAuth2ClientAuthenticationToken clientPrincipal = new OAuth2ClientAuthenticationToken(registeredClient, ClientAuthenticationMethod.CLIENT_SECRET_BASIC, registeredClient.getClientSecret());
    OAuth2ClientCredentialsAuthenticationToken clientCredentialsAuthentication = new OAuth2ClientCredentialsAuthenticationToken(clientPrincipal, null, null);
    given(authenticationConverter.convert(any())).willReturn(clientCredentialsAuthentication);
    OAuth2AccessToken accessToken = new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER, "token", Instant.now(), Instant.now().plus(Duration.ofHours(1)));
    OAuth2AccessTokenAuthenticationToken accessTokenAuthentication = new OAuth2AccessTokenAuthenticationToken(registeredClient, clientPrincipal, accessToken);
    given(authenticationProvider.supports(eq(OAuth2ClientCredentialsAuthenticationToken.class))).willReturn(true);
    given(authenticationProvider.authenticate(any())).willReturn(accessTokenAuthentication);
    this.mvc.perform(post(DEFAULT_TOKEN_ENDPOINT_URI).param(OAuth2ParameterNames.GRANT_TYPE, AuthorizationGrantType.CLIENT_CREDENTIALS.getValue()).header(HttpHeaders.AUTHORIZATION, "Basic " + encodeBasicAuth(registeredClient.getClientId(), registeredClient.getClientSecret()))).andExpect(status().isOk());
    verify(authenticationConverter).convert(any());
    @SuppressWarnings("unchecked")
    ArgumentCaptor<List<AuthenticationConverter>> authenticationConvertersCaptor = ArgumentCaptor.forClass(List.class);
    verify(authenticationConvertersConsumer).accept(authenticationConvertersCaptor.capture());
    List<AuthenticationConverter> authenticationConverters = authenticationConvertersCaptor.getValue();
    assertThat(authenticationConverters).allMatch((converter) -> converter == authenticationConverter || converter instanceof OAuth2AuthorizationCodeAuthenticationConverter || converter instanceof OAuth2RefreshTokenAuthenticationConverter || converter instanceof OAuth2ClientCredentialsAuthenticationConverter || converter instanceof OAuth2DeviceCodeAuthenticationConverter || converter instanceof OAuth2TokenExchangeAuthenticationConverter);
    verify(authenticationProvider).authenticate(eq(clientCredentialsAuthentication));
    @SuppressWarnings("unchecked")
    ArgumentCaptor<List<AuthenticationProvider>> authenticationProvidersCaptor = ArgumentCaptor.forClass(List.class);
    verify(authenticationProvidersConsumer).accept(authenticationProvidersCaptor.capture());
    List<AuthenticationProvider> authenticationProviders = authenticationProvidersCaptor.getValue();
    assertThat(authenticationProviders).allMatch((provider) -> provider == authenticationProvider || provider instanceof OAuth2AuthorizationCodeAuthenticationProvider || provider instanceof OAuth2RefreshTokenAuthenticationProvider || provider instanceof OAuth2ClientCredentialsAuthenticationProvider || provider instanceof OAuth2DeviceCodeAuthenticationProvider || provider instanceof OAuth2TokenExchangeAuthenticationProvider);
    verify(authenticationSuccessHandler).onAuthenticationSuccess(any(), any(), eq(accessTokenAuthentication));
}

