@Test
public void requestWhenDeviceAuthorizationRequestValidThenReturnDeviceAuthorizationResponse() throws Exception {
    this.spring.register(AuthorizationServerConfigurationWithMultipleIssuersAllowed.class).autowire();
    // @formatter:off
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().authorizationGrantType(AuthorizationGrantType.DEVICE_CODE).build();
    // @formatter:on
    this.registeredClientRepository.save(registeredClient);
    MultiValueMap<String, String> parameters = new LinkedMultiValueMap<>();
    parameters.set(OAuth2ParameterNames.CLIENT_ID, registeredClient.getClientId());
    parameters.set(OAuth2ParameterNames.SCOPE, StringUtils.collectionToDelimitedString(registeredClient.getScopes(), " "));
    String issuer = "https://example.com:8443/issuer1";
    // @formatter:off
    MvcResult mvcResult = this.mvc.perform(post(issuer.concat(DEFAULT_DEVICE_AUTHORIZATION_ENDPOINT_URI)).params(parameters).headers(withClientAuth(registeredClient))).andExpect(status().isOk()).andExpect(jsonPath("$.device_code").isNotEmpty()).andExpect(jsonPath("$.user_code").isNotEmpty()).andExpect(jsonPath("$.expires_in").isNumber()).andExpect(jsonPath("$.verification_uri").isNotEmpty()).andExpect(jsonPath("$.verification_uri_complete").isNotEmpty()).andReturn();
    // @formatter:on
    MockHttpServletResponse servletResponse = mvcResult.getResponse();
    MockClientHttpResponse httpResponse = new MockClientHttpResponse(servletResponse.getContentAsByteArray(), HttpStatus.OK);
    OAuth2DeviceAuthorizationResponse deviceAuthorizationResponse = deviceAuthorizationResponseHttpMessageConverter.read(OAuth2DeviceAuthorizationResponse.class, httpResponse);
    String userCode = deviceAuthorizationResponse.getUserCode().getTokenValue();
    assertThat(userCode).matches("[A-Z]{4}-[A-Z]{4}");
    assertThat(deviceAuthorizationResponse.getVerificationUri()).isEqualTo("https://example.com:8443/oauth2/device_verification");
    assertThat(deviceAuthorizationResponse.getVerificationUriComplete()).isEqualTo("https://example.com:8443/oauth2/device_verification?user_code=" + userCode);
    String deviceCode = deviceAuthorizationResponse.getDeviceCode().getTokenValue();
    OAuth2Authorization authorization = this.authorizationService.findByToken(deviceCode, DEVICE_CODE_TOKEN_TYPE);
    assertThat(authorization.getToken(OAuth2DeviceCode.class)).isNotNull();
    assertThat(authorization.getToken(OAuth2UserCode.class)).isNotNull();
}

