@Test
public void requestWhenAuthenticationRequestThenTokenResponseIncludesIdToken() throws Exception {
    this.spring.register(AuthorizationServerConfiguration.class).autowire();
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().scope(OidcScopes.OPENID).build();
    this.registeredClientRepository.save(registeredClient);
    MultiValueMap<String, String> authorizationRequestParameters = getAuthorizationRequestParameters(registeredClient);
    MvcResult mvcResult = this.mvc.perform(get(DEFAULT_AUTHORIZATION_ENDPOINT_URI).queryParams(authorizationRequestParameters).with(user("user").roles("A", "B"))).andExpect(status().is3xxRedirection()).andReturn();
    String redirectedUrl = mvcResult.getResponse().getRedirectedUrl();
    String expectedRedirectUri = authorizationRequestParameters.getFirst(OAuth2ParameterNames.REDIRECT_URI);
    assertThat(redirectedUrl).matches(expectedRedirectUri + "\\?code=.{15,}&state=state");
    String authorizationCode = extractParameterFromRedirectUri(redirectedUrl, "code");
    OAuth2Authorization authorization = this.authorizationService.findByToken(authorizationCode, AUTHORIZATION_CODE_TOKEN_TYPE);
    mvcResult = this.mvc.perform(post(DEFAULT_TOKEN_ENDPOINT_URI).params(getTokenRequestParameters(registeredClient, authorization)).header(HttpHeaders.AUTHORIZATION, "Basic " + encodeBasicAuth(registeredClient.getClientId(), registeredClient.getClientSecret()))).andExpect(status().isOk()).andExpect(header().string(HttpHeaders.CACHE_CONTROL, containsString("no-store"))).andExpect(header().string(HttpHeaders.PRAGMA, containsString("no-cache"))).andExpect(jsonPath("$.access_token").isNotEmpty()).andExpect(jsonPath("$.token_type").isNotEmpty()).andExpect(jsonPath("$.expires_in").isNotEmpty()).andExpect(jsonPath("$.refresh_token").isNotEmpty()).andExpect(jsonPath("$.scope").isNotEmpty()).andExpect(jsonPath("$.id_token").isNotEmpty()).andReturn();
    MockHttpServletResponse servletResponse = mvcResult.getResponse();
    MockClientHttpResponse httpResponse = new MockClientHttpResponse(servletResponse.getContentAsByteArray(), HttpStatus.valueOf(servletResponse.getStatus()));
    OAuth2AccessTokenResponse accessTokenResponse = accessTokenHttpResponseConverter.read(OAuth2AccessTokenResponse.class, httpResponse);
    Jwt idToken = this.jwtDecoder.decode((String) accessTokenResponse.getAdditionalParameters().get(OidcParameterNames.ID_TOKEN));
    // Assert user authorities was propagated as claim in ID Token
    List<String> authoritiesClaim = idToken.getClaim(AUTHORITIES_CLAIM);
    Authentication principal = authorization.getAttribute(Principal.class.getName());
    Set<String> userAuthorities = new HashSet<>();
    for (GrantedAuthority authority : principal.getAuthorities()) {
        userAuthorities.add(authority.getAuthority());
    }
    assertThat(authoritiesClaim).containsExactlyInAnyOrderElementsOf(userAuthorities);
    // Assert sid claim was added in ID Token
    assertThat(idToken.<String>getClaim("sid")).isNotNull();
}

