@Test
public void requestWhenLogoutRequestThenLogout() throws Exception {
    this.spring.register(AuthorizationServerConfiguration.class).autowire();
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().scope(OidcScopes.OPENID).build();
    this.registeredClientRepository.save(registeredClient);
    String issuer = "https://example.com:8443/issuer1";
    // Login
    MultiValueMap<String, String> authorizationRequestParameters = getAuthorizationRequestParameters(registeredClient);
    MvcResult mvcResult = this.mvc.perform(get(issuer.concat(DEFAULT_AUTHORIZATION_ENDPOINT_URI)).queryParams(authorizationRequestParameters).with(user("user"))).andExpect(status().is3xxRedirection()).andReturn();
    MockHttpSession session = (MockHttpSession) mvcResult.getRequest().getSession();
    assertThat(session.isNew()).isTrue();
    String redirectedUrl = mvcResult.getResponse().getRedirectedUrl();
    String authorizationCode = extractParameterFromRedirectUri(redirectedUrl, "code");
    OAuth2Authorization authorization = this.authorizationService.findByToken(authorizationCode, AUTHORIZATION_CODE_TOKEN_TYPE);
    // Get ID Token
    mvcResult = this.mvc.perform(post(issuer.concat(DEFAULT_TOKEN_ENDPOINT_URI)).params(getTokenRequestParameters(registeredClient, authorization)).header(HttpHeaders.AUTHORIZATION, "Basic " + encodeBasicAuth(registeredClient.getClientId(), registeredClient.getClientSecret()))).andExpect(status().isOk()).andReturn();
    MockHttpServletResponse servletResponse = mvcResult.getResponse();
    MockClientHttpResponse httpResponse = new MockClientHttpResponse(servletResponse.getContentAsByteArray(), HttpStatus.valueOf(servletResponse.getStatus()));
    OAuth2AccessTokenResponse accessTokenResponse = accessTokenHttpResponseConverter.read(OAuth2AccessTokenResponse.class, httpResponse);
    String idToken = (String) accessTokenResponse.getAdditionalParameters().get(OidcParameterNames.ID_TOKEN);
    // Logout
    mvcResult = this.mvc.perform(post(issuer.concat(DEFAULT_OIDC_LOGOUT_ENDPOINT_URI)).param("id_token_hint", idToken).session(session)).andExpect(status().is3xxRedirection()).andReturn();
    redirectedUrl = mvcResult.getResponse().getRedirectedUrl();
    assertThat(redirectedUrl).matches("/");
    assertThat(session.isInvalid()).isTrue();
}

