@Test
public void requireExplicitSave() throws Exception {
    HttpSessionSecurityContextRepository repository = new HttpSessionSecurityContextRepository();
    SpringTestContext testContext = this.spring.register(RequireExplicitSaveConfig.class);
    testContext.autowire();
    FilterChainProxy filterChainProxy = testContext.getContext().getBean(FilterChainProxy.class);
    // @formatter:off
    List<Class<? extends Filter>> filterTypes = filterChainProxy.getFilters("/").stream().map(Filter::getClass).collect(Collectors.toList());
    assertThat(filterTypes).contains(SecurityContextHolderFilter.class).doesNotContain(SecurityContextPersistenceFilter.class);
