public void changeSessionIdThenPreserveParameters() throws Exception {
    MockHttpServletRequest request = TestMockHttpServletRequests.post("/login").param("username", "user").param("password", "password").build();
    request.getSession();
    request.getSession().setAttribute("attribute1", "value1");
    String id = request.getSession().getId();
    // @formatter:off
    loadContext("<http>\n" + "        <intercept-url pattern=\"/**\" access=\"authenticated\"/>\n" + "        <form-login/>\n" + "        <session-management/>\n" + "        <csrf disabled='true'/>\n" + "    </http>" + XML_AUTHENTICATION_MANAGER);
    // @formatter:on
    this.springSecurityFilterChain.doFilter(request, this.response, this.chain);
    assertThat(request.getSession().getId()).isNotEqualTo(id);
