@Test
public void multipleLogoutHandlers() {
    InMemorySecurityContextRepository repository = new InMemorySecurityContextRepository();
    MultiValueMap<String, String> logoutData = new LinkedMultiValueMap<>();
    ServerLogoutHandler handler1 = (exchange, authentication) -> {
        logoutData.add("handler-header", "value1");
        return Mono.empty();
    };
    ServerLogoutHandler handler2 = (exchange, authentication) -> {
        logoutData.add("handler-header", "value2");
        return Mono.empty();
    };
    // @formatter:off
    SecurityWebFilterChain securityWebFilter = this.http.securityContextRepository(repository).authorizeExchange((authorize) -> authorize.anyExchange().authenticated()).formLogin(withDefaults()).logout((logoutSpec) -> logoutSpec.logoutHandler((handlers) -> {
        handlers.add(handler1);
        handlers.add(0, handler2);
    })).build();
    WebTestClient webTestClient = WebTestClientBuilder.bindToWebFilters(securityWebFilter).build();
    WebDriver driver = WebTestClientHtmlUnitDriverBuilder.webTestClientSetup(webTestClient).build();
    // @formatter:on
    FormLoginTests.DefaultLoginPage loginPage = FormLoginTests.HomePage.to(driver, FormLoginTests.DefaultLoginPage.class).assertAt();
    // @formatter:off
    loginPage = loginPage.loginForm().username("user").password("invalid").submit(FormLoginTests.DefaultLoginPage.class).assertError();
    FormLoginTests.HomePage homePage = loginPage.loginForm().username("user").password("password").submit(FormLoginTests.HomePage.class);
    // @formatter:on
    homePage.assertAt();
    SecurityContext savedContext = repository.getSavedContext();
    assertThat(savedContext).isNotNull();
    assertThat(savedContext.getAuthentication()).isInstanceOf(UsernamePasswordAuthenticationToken.class);
    loginPage = FormLoginTests.DefaultLogoutPage.to(driver).assertAt().logout();
    loginPage.assertAt().assertLogout();
    assertThat(logoutData).hasSize(1);
    assertThat(logoutData.get("handler-header")).containsExactly("value2", "value1");
    savedContext = repository.getSavedContext();
    assertThat(savedContext).isNull();
}

