@Test
void loginWhenMaxSessionPreventsLoginThenSecondLoginFails() {
    this.spring.register(ConcurrentSessionsMaxSessionPreventsLoginConfig.class).autowire();
    MultiValueMap<String, String> data = new LinkedMultiValueMap<>();
    data.add("username", "user");
    data.add("password", "password");
    ResponseCookie firstLoginSessionCookie = loginReturningCookie(data);
    // second login should fail
    ResponseCookie secondLoginSessionCookie = this.client.mutateWith(csrf()).post().uri("/login").contentType(MediaType.MULTIPART_FORM_DATA).body(BodyInserters.fromFormData(data)).exchange().expectHeader().location("/login?error").returnResult(Void.class).getResponseCookies().getFirst("SESSION");
    assertThat(secondLoginSessionCookie).isNull();
    // first login should still be valid
    this.client.mutateWith(csrf()).get().uri("/").cookie(firstLoginSessionCookie.getName(), firstLoginSessionCookie.getValue()).exchange().expectStatus().isOk();
}

@Test
void httpBasicWhenUsingSavingAuthenticationInWebSessionAndPreventLoginThenSecondRequestFails() {
    this.spring.register(ConcurrentSessionsHttpBasicWithWebSessionMaxSessionPreventsLoginConfig.class).autowire();
    MultiValueMap<String, String> data = new LinkedMultiValueMap<>();
    data.add("username", "user");
    data.add("password", "password");
    // first request be successful
    ResponseCookie sessionCookie = this.client.get().uri("/").headers((headers) -> headers.setBasicAuth("user", "password")).exchange().expectStatus().isOk().expectCookie().exists("SESSION").returnResult(Void.class).getResponseCookies().getFirst("SESSION");
    // request with no session should fail
    this.client.get().uri("/").headers((headers) -> headers.setBasicAuth("user", "password")).exchange().expectStatus().isUnauthorized();
    // request with session obtained from first request should be successful
    this.client.get().uri("/").headers((headers) -> headers.setBasicAuth("user", "password")).cookie(sessionCookie.getName(), sessionCookie.getValue()).exchange().expectStatus().isOk();
}

@Test
void loginWhenMaxSessionPerAuthenticationThenUserLoginFailsAndAdminLoginSucceeds() {
    ConcurrentSessionsMaxSessionPreventsLoginConfig.sessionLimit = (authentication) -> {
        if (authentication.getName().equals("admin")) {
            return Mono.empty();
        }
        return Mono.just(1);
    };
    this.spring.register(ConcurrentSessionsMaxSessionPreventsLoginConfig.class).autowire();
    MultiValueMap<String, String> data = new LinkedMultiValueMap<>();
    data.add("username", "user");
    data.add("password", "password");
    MultiValueMap<String, String> adminCreds = new LinkedMultiValueMap<>();
    adminCreds.add("username", "admin");
    adminCreds.add("password", "password");
    ResponseCookie userFirstLoginSessionCookie = loginReturningCookie(data);
    ResponseCookie adminFirstLoginSessionCookie = loginReturningCookie(adminCreds);
    // second user login should fail
    this.client.mutateWith(csrf()).post().uri("/login").contentType(MediaType.MULTIPART_FORM_DATA).body(BodyInserters.fromFormData(data)).exchange().expectHeader().location("/login?error");
    // first login should still be valid
    this.client.mutateWith(csrf()).get().uri("/").cookie(userFirstLoginSessionCookie.getName(), userFirstLoginSessionCookie.getValue()).exchange().expectStatus().isOk();
    ResponseCookie adminSecondLoginSessionCookie = loginReturningCookie(adminCreds);
    this.client.mutateWith(csrf()).get().uri("/").cookie(adminFirstLoginSessionCookie.getName(), adminFirstLoginSessionCookie.getValue()).exchange().expectStatus().isOk();
    this.client.mutateWith(csrf()).get().uri("/").cookie(adminSecondLoginSessionCookie.getName(), adminSecondLoginSessionCookie.getValue()).exchange().expectStatus().isOk();
}

