@Test
void allSerializableClassesShouldHaveSerialVersionOrSuppressWarnings() throws Exception {
    ClassPathScanningCandidateComponentProvider provider = new ClassPathScanningCandidateComponentProvider(false);
    provider.addIncludeFilter(new AssignableTypeFilter(Serializable.class));
    List<Class<?>> classes = new ArrayList<>();
    Set<BeanDefinition> components = provider.findCandidateComponents("org/springframework/security");
    for (BeanDefinition component : components) {
        Class<?> clazz = Class.forName(component.getBeanClassName());
        if (clazz.isEnum()) {
            continue;
        }
        if (clazz.getName().contains("Tests")) {
            continue;
        }
        boolean hasSerialVersion = Stream.of(clazz.getDeclaredFields()).map(Field::getName).anyMatch((n) -> n.equals("serialVersionUID"));
        SuppressWarnings suppressWarnings = clazz.getAnnotation(SuppressWarnings.class);
        boolean hasSerialIgnore = suppressWarnings == null || Arrays.asList(suppressWarnings.value()).contains("Serial");
        if (!hasSerialVersion && !hasSerialIgnore) {
            classes.add(clazz);
            continue;
        }
        boolean isReachable = Modifier.isPublic(clazz.getModifiers());
        boolean hasSampleSerialization = currentVersionFolder.resolve(clazz.getName() + ".serialized").toFile().exists();
        if (hasSerialVersion && isReachable && !hasSampleSerialization) {
            classes.add(clazz);
        }
    }
    assertThat(classes).describedAs("Found Serializable classes that are either missing a serialVersionUID or a @SuppressWarnings or a sample serialized file").isEmpty();
}

