@Test
public void registerHintsWhenUsingAuthorizeReturnObjectThenRegisters() {
    GenericApplicationContext context = new GenericApplicationContext();
    context.registerBean(MyService.class, MyService::new);
    context.registerBean(MyInterface.class, MyImplementation::new);
    context.refresh();
    RuntimeHints hints = new RuntimeHints();
    this.registrar.registerHints(hints, context.getBeanFactory());
    assertThat(hints.reflection().typeHints().map((hint) -> hint.getType().getName())).containsOnly(cglibClassName(MyObject.class), cglibClassName(MySubObject.class), MyObject.class.getName(), MySubObject.class.getName());
    assertThat(hints.proxies().jdkProxyHints().flatMap((hint) -> hint.getProxiedInterfaces().stream()).map(TypeReference::getName)).contains(MyInterface.class.getName());
}

