@Test
void toBuilderWhenApplyThenCopies() {
    JaasAuthenticationToken factorOne = new JaasAuthenticationToken("alice", "pass", AuthorityUtils.createAuthorityList("FACTOR_ONE"), mock(LoginContext.class));
    JaasAuthenticationToken factorTwo = new JaasAuthenticationToken("bob", "ssap", AuthorityUtils.createAuthorityList("FACTOR_TWO"), mock(LoginContext.class));
    JaasAuthenticationToken result = factorOne.toBuilder().authorities((a) -> a.addAll(factorTwo.getAuthorities())).principal(factorTwo.getPrincipal()).credentials(factorTwo.getCredentials()).loginContext(factorTwo.getLoginContext()).build();
    Set<String> authorities = AuthorityUtils.authorityListToSet(result.getAuthorities());
    assertThat(result.getPrincipal()).isSameAs(factorTwo.getPrincipal());
    assertThat(result.getCredentials()).isSameAs(factorTwo.getCredentials());
    assertThat(result.getLoginContext()).isSameAs(factorTwo.getLoginContext());
    assertThat(authorities).containsExactlyInAnyOrder("FACTOR_ONE", "FACTOR_TWO");
}

