@Test
void authorizeWhenJustExpired() {
    Instant now = Instant.now();
    Duration expiresIn = Duration.ofHours(1);
    Instant justExpired = now.minus(expiresIn);
    Clock clock = Clock.fixed(now, ZoneId.systemDefault());
    RequiredFactor expiringPassword = RequiredFactor.withAuthority(FactorGrantedAuthority.PASSWORD_AUTHORITY).validDuration(expiresIn).build();
    AllRequiredFactorsAuthorizationManager<Object> allFactors = AllRequiredFactorsAuthorizationManager.builder().requireFactor(expiringPassword).build();
    allFactors.setClock(clock);
    FactorGrantedAuthority passwordFactor = FactorGrantedAuthority.withAuthority(expiringPassword.getAuthority()).issuedAt(justExpired).build();
    Authentication authentication = new TestingAuthenticationToken("user", "password", passwordFactor);
    FactorAuthorizationDecision result = allFactors.authorize(() -> authentication, DOES_NOT_MATTER);
    assertThat(result.isGranted()).isFalse();
    assertThat(result.getFactorErrors()).containsExactly(RequiredFactorError.createExpired(expiringPassword));
}

