@Test
void authorizationOrdered() throws Exception {
    this.spring.register(CustomizerBeanOrderingConfiguration.class).autowire();
    // @formatter:off
    this.webTest.mutateWith(mockUser("admin").roles("ADMIN")).get().uri("https://localhost/admins/1").exchange().expectStatus().isOk();
    this.webTest.mutateWith(mockUser("user").roles("USER")).get().uri("https://localhost/admins/1").exchange().expectStatus().isForbidden();
    this.webTest.mutateWith(mockUser("user").roles("USER")).get().uri("https://localhost/users/1").exchange().expectStatus().isOk();
    this.webTest.mutateWith(mockUser("user").roles("OTHER")).get().uri("https://localhost/users/1").exchange().expectStatus().isForbidden();
    this.webTest.mutateWith(mockUser("authenticated").roles("OTHER")).get().uri("https://localhost/other").exchange().expectStatus().isOk();
    // @formatter:on
}

