@Test
void toBuilderWhenApplyThenCopies() {
    UsernamePasswordAuthenticationToken previous = new UsernamePasswordAuthenticationToken("alice", "pass", AuthorityUtils.createAuthorityList(FactorGrantedAuthority.PASSWORD_AUTHORITY));
    SecurityContextHolder.getContext().setAuthentication(previous);
    Authentication latest = new OneTimeTokenAuthentication("bob", AuthorityUtils.createAuthorityList(FactorGrantedAuthority.OTT_AUTHORITY));
    AuthenticationManager authenticationManager = mock(AuthenticationManager.class);
    given(authenticationManager.authenticate(any())).willReturn(latest);
    Authentication authenticationRequest = new TestingAuthenticationToken("user", "pass");
    // tag::springSecurity[]
    Authentication lastestResult = authenticationManager.authenticate(authenticationRequest);
    Authentication previousResult = SecurityContextHolder.getContext().getAuthentication();
    if (previousResult != null && previousResult.isAuthenticated()) {
        lastestResult = lastestResult.toBuilder().authorities((a) -> a.addAll(previous.getAuthorities())).build();
    }
    // end::springSecurity[]
    SecurityAssertions.assertThat(lastestResult).hasAuthorities(FactorGrantedAuthority.PASSWORD_AUTHORITY, FactorGrantedAuthority.OTT_AUTHORITY);
    SecurityContextHolder.clearContext();
}

