    MessageHeaders headers2 = new MessageHeaders(Map.of(SimpMessageHeaderAccessor.MESSAGE_TYPE_HEADER, SimpMessageType.SUBSCRIBE, SimpMessageHeaderAccessor.DESTINATION_HEADER, "/destination"));
    Message<?> message2 = new GenericMessage<>(new Object(), headers2);
    assertThat(authorizationManager.authorize(mock(Supplier.class), message2).isGranted()).isFalse();
}

