    OAuth2Authorization authorization = TestOAuth2Authorizations.authorization(registeredClient, authorizationRequestAdditionalParameters).build();
    given(this.authorizationService.findByToken(eq(AUTHORIZATION_CODE), eq(AUTHORIZATION_CODE_TOKEN_TYPE))).willReturn(authorization);
    Map<String, Object> parameters = createPkceTokenParameters(S256_CODE_VERIFIER);
    OAuth2ClientAuthenticationToken authentication = new OAuth2ClientAuthenticationToken(registeredClient.getClientId(), ClientAuthenticationMethod.NONE, null, parameters);
    assertThatExceptionOfType(OAuth2AuthenticationException.class).isThrownBy(() -> this.authenticationProvider.authenticate(authentication)).extracting(OAuth2AuthenticationException::getError).extracting("errorCode").isEqualTo(OAuth2ErrorCodes.INVALID_GRANT);
}

