@Test
public void saveWhenInitializedAuthorizationsReachMaxThenOldestRemoved() {
    int maxInitializedAuthorizations = 5;
    InMemoryOAuth2AuthorizationService authorizationService = new InMemoryOAuth2AuthorizationService(maxInitializedAuthorizations);
    OAuth2Authorization initialAuthorization = OAuth2Authorization.withRegisteredClient(REGISTERED_CLIENT).id(ID + "-initial").principalName(PRINCIPAL_NAME).authorizationGrantType(AUTHORIZATION_GRANT_TYPE).attribute(OAuth2ParameterNames.STATE, "state-initial").build();
    authorizationService.save(initialAuthorization);
    OAuth2Authorization authorization = authorizationService.findById(initialAuthorization.getId());
    assertThat(authorization).isEqualTo(initialAuthorization);
    authorization = authorizationService.findByToken(initialAuthorization.getAttribute(OAuth2ParameterNames.STATE), STATE_TOKEN_TYPE);
    assertThat(authorization).isEqualTo(initialAuthorization);
    for (int i = 0; i < maxInitializedAuthorizations; i++) {
        authorization = OAuth2Authorization.withRegisteredClient(REGISTERED_CLIENT).id(ID + "-" + i).principalName(PRINCIPAL_NAME).authorizationGrantType(AUTHORIZATION_GRANT_TYPE).attribute(OAuth2ParameterNames.STATE, "state-" + i).build();
        authorizationService.save(authorization);
    }
    authorization = authorizationService.findById(initialAuthorization.getId());
    assertThat(authorization).isNull();
    authorization = authorizationService.findByToken(initialAuthorization.getAttribute(OAuth2ParameterNames.STATE), STATE_TOKEN_TYPE);
    assertThat(authorization).isNull();
}

