@Test
public void doFilterWhenAuthorizationRequestAuthenticatedThenAuthorizationResponse() throws Exception {
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().redirectUris((redirectUris) -> {
        redirectUris.clear();
        redirectUris.add("https://example.com?param=encoded%20parameter%20value");
    }).build();
    OAuth2AuthorizationCodeRequestAuthenticationToken authorizationCodeRequestAuthenticationResult = new OAuth2AuthorizationCodeRequestAuthenticationToken(AUTHORIZATION_URI, registeredClient.getClientId(), this.principal, this.authorizationCode, registeredClient.getRedirectUris().iterator().next(), "client state", registeredClient.getScopes());
    authorizationCodeRequestAuthenticationResult.setAuthenticated(true);
    given(this.authenticationManager.authenticate(any())).willReturn(authorizationCodeRequestAuthenticationResult);
    MockHttpServletRequest request = createAuthorizationRequest(registeredClient);
    request.addParameter("custom-param", "custom-value-1", "custom-value-2");
    updateQueryString(request);
    MockHttpServletResponse response = new MockHttpServletResponse();
    FilterChain filterChain = mock(FilterChain.class);
    this.filter.doFilter(request, response, filterChain);
    ArgumentCaptor<OAuth2AuthorizationCodeRequestAuthenticationToken> authorizationCodeRequestAuthenticationCaptor = ArgumentCaptor.forClass(OAuth2AuthorizationCodeRequestAuthenticationToken.class);
    verify(this.authenticationManager).authenticate(authorizationCodeRequestAuthenticationCaptor.capture());
    verifyNoInteractions(filterChain);
    assertThat(authorizationCodeRequestAuthenticationCaptor.getValue().getDetails()).asInstanceOf(InstanceOfAssertFactories.type(WebAuthenticationDetails.class)).extracting(WebAuthenticationDetails::getRemoteAddress).isEqualTo(REMOTE_ADDRESS);
    // Assert that multi-valued request parameters are preserved
    assertThat(authorizationCodeRequestAuthenticationCaptor.getValue().getAdditionalParameters()).extracting((params) -> params.get("custom-param")).asInstanceOf(InstanceOfAssertFactories.type(String[].class)).isEqualTo(new String[] { "custom-value-1", "custom-value-2" });
    assertThat(response.getStatus()).isEqualTo(HttpStatus.FOUND.value());
    assertThat(response.getRedirectedUrl()).isEqualTo("https://example.com?param=encoded%20parameter%20value&code=code&state=client%20state");
}

