@Test
public void doFilterWhenClientRegistrationRequestValidThenSuccessResponse() throws Exception {
    // @formatter:off
    OAuth2ClientRegistration expectedClientRegistrationResponse = createClientRegistration();
    OAuth2ClientRegistration clientRegistrationRequest = OAuth2ClientRegistration.builder().clientName(expectedClientRegistrationResponse.getClientName()).redirectUris((redirectUris) -> redirectUris.addAll(expectedClientRegistrationResponse.getRedirectUris())).grantTypes((grantTypes) -> grantTypes.addAll(expectedClientRegistrationResponse.getGrantTypes())).scopes((scopes) -> scopes.addAll(expectedClientRegistrationResponse.getScopes())).build();
    // @formatter:on
    Jwt jwt = createJwt("client.create");
    JwtAuthenticationToken principal = new JwtAuthenticationToken(jwt, AuthorityUtils.createAuthorityList("SCOPE_client.create"));
    OAuth2ClientRegistrationAuthenticationToken clientRegistrationAuthenticationResult = new OAuth2ClientRegistrationAuthenticationToken(principal, expectedClientRegistrationResponse);
    given(this.authenticationManager.authenticate(any())).willReturn(clientRegistrationAuthenticationResult);
    SecurityContext securityContext = SecurityContextHolder.createEmptyContext();
    securityContext.setAuthentication(principal);
    SecurityContextHolder.setContext(securityContext);
    String requestUri = DEFAULT_OAUTH2_CLIENT_REGISTRATION_ENDPOINT_URI;
    MockHttpServletRequest request = new MockHttpServletRequest("POST", requestUri);
    request.setServletPath(requestUri);
    writeClientRegistrationRequest(request, clientRegistrationRequest);
    MockHttpServletResponse response = new MockHttpServletResponse();
    FilterChain filterChain = mock(FilterChain.class);
    this.filter.doFilter(request, response, filterChain);
    verifyNoInteractions(filterChain);
    assertThat(response.getStatus()).isEqualTo(HttpStatus.CREATED.value());
    OAuth2ClientRegistration clientRegistrationResponse = readClientRegistrationResponse(response);
    assertThat(clientRegistrationResponse.getClientId()).isEqualTo(expectedClientRegistrationResponse.getClientId());
    assertThat(clientRegistrationResponse.getClientIdIssuedAt()).isBetween(expectedClientRegistrationResponse.getClientIdIssuedAt().minusSeconds(1), expectedClientRegistrationResponse.getClientIdIssuedAt().plusSeconds(1));
    assertThat(clientRegistrationResponse.getClientSecret()).isEqualTo(expectedClientRegistrationResponse.getClientSecret());
    assertThat(clientRegistrationResponse.getClientSecretExpiresAt()).isEqualTo(expectedClientRegistrationResponse.getClientSecretExpiresAt());
    assertThat(clientRegistrationResponse.getClientName()).isEqualTo(expectedClientRegistrationResponse.getClientName());
    assertThat(clientRegistrationResponse.getRedirectUris()).containsExactlyInAnyOrderElementsOf(expectedClientRegistrationResponse.getRedirectUris());
    assertThat(clientRegistrationResponse.getGrantTypes()).containsExactlyInAnyOrderElementsOf(expectedClientRegistrationResponse.getGrantTypes());
    assertThat(clientRegistrationResponse.getResponseTypes()).containsExactlyInAnyOrderElementsOf(expectedClientRegistrationResponse.getResponseTypes());
    assertThat(clientRegistrationResponse.getScopes()).containsExactlyInAnyOrderElementsOf(expectedClientRegistrationResponse.getScopes());
    assertThat(clientRegistrationResponse.getTokenEndpointAuthenticationMethod()).isEqualTo(expectedClientRegistrationResponse.getTokenEndpointAuthenticationMethod());
}

