@Test
public void doFilterWhenPushedAuthorizationRequestAuthenticatedThenPushedAuthorizationResponse() throws Exception {
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().build();
    String requestUri = OAuth2ParameterNames.REQUEST_URI;
    Instant requestUriExpiresAt = Instant.now().plusSeconds(30);
    OAuth2PushedAuthorizationRequestAuthenticationToken pushedAuthorizationRequestAuthenticationResult = new OAuth2PushedAuthorizationRequestAuthenticationToken(AUTHORIZATION_URI, registeredClient.getClientId(), this.clientPrincipal, requestUri, requestUriExpiresAt, registeredClient.getRedirectUris().iterator().next(), STATE, registeredClient.getScopes());
    given(this.authenticationManager.authenticate(any())).willReturn(pushedAuthorizationRequestAuthenticationResult);
    MockHttpServletRequest request = createPushedAuthorizationRequest(registeredClient);
    request.addParameter("custom-param", "custom-value-1", "custom-value-2");
    MockHttpServletResponse response = new MockHttpServletResponse();
    FilterChain filterChain = mock(FilterChain.class);
    this.filter.doFilter(request, response, filterChain);
    ArgumentCaptor<OAuth2PushedAuthorizationRequestAuthenticationToken> pushedAuthorizationRequestAuthenticationCaptor = ArgumentCaptor.forClass(OAuth2PushedAuthorizationRequestAuthenticationToken.class);
    verify(this.authenticationManager).authenticate(pushedAuthorizationRequestAuthenticationCaptor.capture());
    verifyNoInteractions(filterChain);
    assertThat(pushedAuthorizationRequestAuthenticationCaptor.getValue().getDetails()).asInstanceOf(InstanceOfAssertFactories.type(WebAuthenticationDetails.class)).extracting(WebAuthenticationDetails::getRemoteAddress).isEqualTo(REMOTE_ADDRESS);
    // Assert that multi-valued request parameters are preserved
    assertThat(pushedAuthorizationRequestAuthenticationCaptor.getValue().getAdditionalParameters()).extracting((params) -> params.get("custom-param")).asInstanceOf(InstanceOfAssertFactories.type(String[].class)).isEqualTo(new String[] { "custom-value-1", "custom-value-2" });
    assertThat(response.getStatus()).isEqualTo(HttpStatus.CREATED.value());
    Map<String, Object> responseParameters = readPushedAuthorizationResponse(response);
    assertThat(responseParameters.get(OAuth2ParameterNames.REQUEST_URI)).isEqualTo(requestUri);
    Instant requestUriExpiry = Instant.now().plusSeconds(Long.parseLong(String.valueOf(responseParameters.get("expires_in"))));
