@Test
public void doFilterWhenAuthorizationCodeTokenRequestThenAccessTokenResponse() throws Exception {
    RegisteredClient registeredClient = TestRegisteredClients.registeredClient().build();
    Authentication clientPrincipal = new OAuth2ClientAuthenticationToken(registeredClient, ClientAuthenticationMethod.CLIENT_SECRET_BASIC, registeredClient.getClientSecret());
    OAuth2AccessToken accessToken = new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER, "token", Instant.now(), Instant.now().plus(Duration.ofHours(1)), new HashSet<>(Arrays.asList("scope1", "scope2")));
    OAuth2RefreshToken refreshToken = new OAuth2RefreshToken("refresh-token", Instant.now(), Instant.now().plus(Duration.ofDays(1)));
    OAuth2AccessTokenAuthenticationToken accessTokenAuthentication = new OAuth2AccessTokenAuthenticationToken(registeredClient, clientPrincipal, accessToken, refreshToken);
    given(this.authenticationManager.authenticate(any())).willReturn(accessTokenAuthentication);
    SecurityContext securityContext = SecurityContextHolder.createEmptyContext();
    securityContext.setAuthentication(clientPrincipal);
    SecurityContextHolder.setContext(securityContext);
    MockHttpServletRequest request = createAuthorizationCodeTokenRequest(registeredClient);
    request.addHeader(OAuth2AccessToken.TokenType.DPOP.getValue(), "dpop-proof-jwt");
    MockHttpServletResponse response = new MockHttpServletResponse();
    FilterChain filterChain = mock(FilterChain.class);
    this.filter.doFilter(request, response, filterChain);
    verifyNoInteractions(filterChain);
    ArgumentCaptor<OAuth2AuthorizationCodeAuthenticationToken> authorizationCodeAuthenticationCaptor = ArgumentCaptor.forClass(OAuth2AuthorizationCodeAuthenticationToken.class);
    verify(this.authenticationManager).authenticate(authorizationCodeAuthenticationCaptor.capture());
    OAuth2AuthorizationCodeAuthenticationToken authorizationCodeAuthentication = authorizationCodeAuthenticationCaptor.getValue();
    assertThat(authorizationCodeAuthentication.getCode()).isEqualTo(request.getParameter(OAuth2ParameterNames.CODE));
    assertThat(authorizationCodeAuthentication.getPrincipal()).isEqualTo(clientPrincipal);
    assertThat(authorizationCodeAuthentication.getRedirectUri()).isEqualTo(request.getParameter(OAuth2ParameterNames.REDIRECT_URI));
    Map<String, Object> expectedAdditionalParameters = new HashMap<>();
    expectedAdditionalParameters.put("custom-param-1", "custom-value-1");
    expectedAdditionalParameters.put("custom-param-2", new String[] { "custom-value-1", "custom-value-2" });
    expectedAdditionalParameters.put("dpop_proof", "dpop-proof-jwt");
    expectedAdditionalParameters.put("dpop_method", "POST");
    expectedAdditionalParameters.put("dpop_target_uri", "http://localhost/oauth2/token");
    assertThat(authorizationCodeAuthentication.getAdditionalParameters()).containsExactlyInAnyOrderEntriesOf(expectedAdditionalParameters);
    assertThat(authorizationCodeAuthentication.getDetails()).asInstanceOf(InstanceOfAssertFactories.type(WebAuthenticationDetails.class)).extracting(WebAuthenticationDetails::getRemoteAddress).isEqualTo(REMOTE_ADDRESS);
    assertThat(response.getStatus()).isEqualTo(HttpStatus.OK.value());
    OAuth2AccessTokenResponse accessTokenResponse = readAccessTokenResponse(response);
    OAuth2AccessToken accessTokenResult = accessTokenResponse.getAccessToken();
    assertThat(accessTokenResult.getTokenType()).isEqualTo(accessToken.getTokenType());
    assertThat(accessTokenResult.getTokenValue()).isEqualTo(accessToken.getTokenValue());
    assertThat(accessTokenResult.getIssuedAt()).isBetween(accessToken.getIssuedAt().minusSeconds(1), accessToken.getIssuedAt().plusSeconds(1));
    assertThat(accessTokenResult.getExpiresAt()).isBetween(accessToken.getExpiresAt().minusSeconds(1), accessToken.getExpiresAt().plusSeconds(1));
    assertThat(accessTokenResult.getScopes()).isEqualTo(accessToken.getScopes());
    assertThat(accessTokenResponse.getRefreshToken().getTokenValue()).isEqualTo(refreshToken.getTokenValue());
}

