@Test
public void loadAuthorizedClientWhenClientRegistrationIsUpdatedThenReturnAuthorizedClientWithUpdatedClientRegistration() {
    ClientRegistration updatedRegistration = ClientRegistration.withClientRegistration(this.registration1).clientSecret("updated secret").build();
    ClientRegistrationRepository clientRegistrationRepository = mock(ClientRegistrationRepository.class);
    given(clientRegistrationRepository.findByRegistrationId(this.registration1.getRegistrationId())).willReturn(this.registration1, updatedRegistration);
    InMemoryOAuth2AuthorizedClientService authorizedClientService = new InMemoryOAuth2AuthorizedClientService(clientRegistrationRepository);
    OAuth2AuthorizedClient cachedAuthorizedClient = new OAuth2AuthorizedClient(this.registration1, this.principalName1, mock(OAuth2AccessToken.class), mock(OAuth2RefreshToken.class));
    authorizedClientService.saveAuthorizedClient(cachedAuthorizedClient, new TestingAuthenticationToken(this.principalName1, null));
    OAuth2AuthorizedClient authorizedClientWithUpdatedRegistration = new OAuth2AuthorizedClient(updatedRegistration, this.principalName1, mock(OAuth2AccessToken.class), mock(OAuth2RefreshToken.class));
    OAuth2AuthorizedClient firstLoadedClient = authorizedClientService.loadAuthorizedClient(this.registration1.getRegistrationId(), this.principalName1);
    OAuth2AuthorizedClient secondLoadedClient = authorizedClientService.loadAuthorizedClient(this.registration1.getRegistrationId(), this.principalName1);
    assertThat(firstLoadedClient).satisfies(isEqualTo(cachedAuthorizedClient));
    assertThat(secondLoadedClient).satisfies(isEqualTo(authorizedClientWithUpdatedRegistration));
}

