@Test
void deserializeWhenClientSettingsPropertyDoesNotExistThenDefaulted() throws JsonProcessingException {
    // ClientRegistration.clientSettings was added later, so old values will be
    // serialized without that property
    // this test checks for passivity
    ClientRegistration clientRegistration = this.clientRegistrationBuilder.build();
    ClientRegistration.ProviderDetails providerDetails = clientRegistration.getProviderDetails();
    ClientRegistration.ProviderDetails.UserInfoEndpoint userInfoEndpoint = providerDetails.getUserInfoEndpoint();
    String scopes = "";
    if (!CollectionUtils.isEmpty(clientRegistration.getScopes())) {
        scopes = StringUtils.collectionToDelimitedString(clientRegistration.getScopes(), ",", """, """);
    }
    String configurationMetadata = ""@class": "java.util.Collections$UnmodifiableMap"";
    if (!CollectionUtils.isEmpty(providerDetails.getConfigurationMetadata())) {
        configurationMetadata += "," + providerDetails.getConfigurationMetadata().keySet().stream().map((key) -> """ + key + "": "" + providerDetails.getConfigurationMetadata().get(key) + """).collect(Collectors.joining(","));
    }
    // @formatter:off
    String json = "{
" + "    "@class": "org.springframework.security.oauth2.client.registration.ClientRegistration",
" + "    "registrationId": "" + clientRegistration.getRegistrationId() + "",
" + "    "clientId": "" + clientRegistration.getClientId() + "",
" + "    "clientSecret": "" + clientRegistration.getClientSecret() + "",
" + "    "clientAuthenticationMethod": {
" + "      "value": "" + clientRegistration.getClientAuthenticationMethod().getValue() + ""
" + "    },
" + "    "authorizationGrantType": {
" + "      "value": "" + clientRegistration.getAuthorizationGrantType().getValue() + ""
" + "    },
" + "    "redirectUri": "" + clientRegistration.getRedirectUri() + "",
" + "    "scopes": [
" + "      "java.util.Collections$UnmodifiableSet",
" + "      [" + scopes + "]
" + "    ],
" + "    "providerDetails": {
" + "      "@class": "org.springframework.security.oauth2.client.registration.ClientRegistration$ProviderDetails",
" + "      "authorizationUri": "" + providerDetails.getAuthorizationUri() + "",
" + "      "tokenUri": "" + providerDetails.getTokenUri() + "",
" + "      "userInfoEndpoint": {
" + "        "@class": "org.springframework.security.oauth2.client.registration.ClientRegistration$ProviderDetails$UserInfoEndpoint",
" + "        "uri": " + ((userInfoEndpoint.getUri() != null) ? """ + userInfoEndpoint.getUri() + """ : null) + ",
" + "        "authenticationMethod": {
" + "          "value": "" + userInfoEndpoint.getAuthenticationMethod().getValue() + ""
" + "        },
" + "        "userNameAttributeName": " + ((userInfoEndpoint.getUserNameAttributeName() != null) ? """ + userInfoEndpoint.getUserNameAttributeName() + """ : null) + "
" + "      },
" + "      "jwkSetUri": " + ((providerDetails.getJwkSetUri() != null) ? """ + providerDetails.getJwkSetUri() + """ : null) + ",
" + "      "issuerUri": " + ((providerDetails.getIssuerUri() != null) ? """ + providerDetails.getIssuerUri() + """ : null) + ",
" + "      "configurationMetadata": {
" + "        " + configurationMetadata + "
" + "      }
" + "    },
" + "    "clientName": "" + clientRegistration.getClientName() + ""
" + "}";
    // @formatter:on
    // validate the test input
    assertThat(json).doesNotContain("clientSettings");
    ClientRegistration registration = this.mapper.readValue(json, ClientRegistration.class);
    // the default value of requireProofKey is false
    assertThat(registration.getClientSettings().isRequireProofKey()).isFalse();
}

