    SecurityContextImpl securityContext = new SecurityContextImpl(this.authentication);
    given(this.securityContextHolderStrategy.getContext()).willReturn(securityContext);
    given(this.jwtDecoder.decode(anyString())).willReturn(jwt);
    OAuth2AuthorizedClientRefreshedEvent authorizedClientRefreshedEvent = new OAuth2AuthorizedClientRefreshedEvent(this.accessTokenResponse, this.authorizedClient);
    assertThatExceptionOfType(OAuth2AuthenticationException.class).isThrownBy(() -> this.eventListener.onApplicationEvent(authorizedClientRefreshedEvent)).withMessageContaining("Invalid issued at time").extracting(OAuth2AuthenticationException::getError).extracting(OAuth2Error::getErrorCode).isEqualTo(INVALID_ID_TOKEN_ERROR);
    verify(this.securityContextHolderStrategy).getContext();
    verify(this.jwtDecoder).decode(this.jwt.getTokenValue());
    verifyNoMoreInteractions(this.securityContextHolderStrategy, this.jwtDecoder);
    verifyNoInteractions(this.userService, this.applicationEventPublisher);
}

