@Test
public void buildWhenAllProvidersThenProvidersAuthorize() throws Exception {
    String accessTokenSuccessResponse = "{\n" + "	\"access_token\": \"access-token-1234\",\n" + "   \"token_type\": \"bearer\",\n" + "   \"expires_in\": \"3600\"\n" + "}\n";
    this.server.enqueue(jsonResponse(accessTokenSuccessResponse));
    this.server.enqueue(jsonResponse(accessTokenSuccessResponse));
    this.server.enqueue(jsonResponse(accessTokenSuccessResponse));
    ReactiveOAuth2AuthorizedClientProvider authorizedClientProvider = ReactiveOAuth2AuthorizedClientProviderBuilder.builder().authorizationCode().refreshToken().clientCredentials().build();
    // authorization_code
    // @formatter:off
    OAuth2AuthorizationContext authorizationCodeContext = OAuth2AuthorizationContext.withClientRegistration(this.clientRegistrationBuilder.build()).principal(this.principal).build();
    // @formatter:on
    assertThatExceptionOfType(ClientAuthorizationRequiredException.class).isThrownBy(() -> authorizedClientProvider.authorize(authorizationCodeContext).block());
    // refresh_token
    OAuth2AuthorizedClient authorizedClient = new OAuth2AuthorizedClient(this.clientRegistrationBuilder.build(), this.principal.getName(), expiredAccessToken(), TestOAuth2RefreshTokens.refreshToken());
    OAuth2AuthorizationContext refreshTokenContext = OAuth2AuthorizationContext.withAuthorizedClient(authorizedClient).principal(this.principal).build();
    OAuth2AuthorizedClient reauthorizedClient = authorizedClientProvider.authorize(refreshTokenContext).block();
    assertThat(reauthorizedClient).isNotNull();
    assertThat(this.server.getRequestCount()).isEqualTo(1);
    RecordedRequest recordedRequest = this.server.takeRequest();
    String formParameters = recordedRequest.getBody().readUtf8();
    assertThat(formParameters).contains("grant_type=refresh_token");
    // client_credentials
    // @formatter:off
    OAuth2AuthorizationContext clientCredentialsContext = OAuth2AuthorizationContext.withClientRegistration(this.clientRegistrationBuilder.authorizationGrantType(AuthorizationGrantType.CLIENT_CREDENTIALS).build()).principal(this.principal).build();
    // @formatter:on
    authorizedClient = authorizedClientProvider.authorize(clientCredentialsContext).block();
    assertThat(authorizedClient).isNotNull();
    assertThat(this.server.getRequestCount()).isEqualTo(2);
    recordedRequest = this.server.takeRequest();
    formParameters = recordedRequest.getBody().readUtf8();
    assertThat(formParameters).contains("grant_type=client_credentials");
}

