@Test
public void filterWhenCustomRedirectStrategySetThenRedirectUriInResponseBody() {
    given(this.clientRepository.findByRegistrationId(this.registration.getRegistrationId())).willReturn(Mono.just(this.registration));
    given(this.authzRequestRepository.saveAuthorizationRequest(any(), any())).willReturn(Mono.empty());
    ServerRedirectStrategy customRedirectStrategy = (exchange, location) -> {
        ServerHttpResponse response = exchange.getResponse();
        response.setStatusCode(HttpStatus.OK);
        response.getHeaders().setContentType(MediaType.TEXT_PLAIN);
        DataBuffer buffer = exchange.getResponse().bufferFactory().wrap(location.toASCIIString().getBytes(StandardCharsets.UTF_8));
        return exchange.getResponse().writeWith(Flux.just(buffer));
    };
    this.filter.setAuthorizationRedirectStrategy(customRedirectStrategy);
    this.filter.setRequestCache(this.requestCache);
    FluxExchangeResult<String> result = this.client.get().uri("https://example.com/oauth2/authorization/registration-id").exchange().expectHeader().contentType(MediaType.TEXT_PLAIN).expectStatus().isOk().returnResult(String.class);
    // @formatter:off
    StepVerifier.create(result.getResponseBody()).assertNext((uri) -> {
        URI location = URI.create(uri);
        assertThat(location).hasScheme("https").hasHost("example.com").hasPath("/login/oauth/authorize").hasParameter("response_type", "code").hasParameter("client_id", "client-id").hasParameter("scope", "read:user").hasParameter("state").hasParameter("redirect_uri", "https://example.com/login/oauth2/code/registration-id");
    }).verifyComplete();
    // @formatter:on
    verifyNoInteractions(this.requestCache);
}

