@Test
public void decodeWhenJoseTypeInvalidThenThrowBadJwtException() throws Exception {
    RSAKey rsaJwk = TestJwks.DEFAULT_RSA_JWK;
    given(this.jwkSource.get(any(), any())).willReturn(Collections.singletonList(rsaJwk));
    String method = "GET";
    String targetUri = "https://resource1";
    // @formatter:off
    Map<String, Object> publicJwk = rsaJwk.toPublicJWK().toJSONObject();
    JwsHeader jwsHeader = JwsHeader.with(SignatureAlgorithm.RS256).type("invalid-type").jwk(publicJwk).build();
    JwtClaimsSet claims = JwtClaimsSet.builder().issuedAt(Instant.now()).claim("htm", method).claim("htu", targetUri).id(UUID.randomUUID().toString()).build();
    // @formatter:on
    Jwt dPoPProof = this.jwtEncoder.encode(JwtEncoderParameters.from(jwsHeader, claims));
    // @formatter:off
    DPoPProofContext dPoPProofContext = DPoPProofContext.withDPoPProof(dPoPProof.getTokenValue()).method(method).targetUri(targetUri).build();
    // @formatter:on
    JwtDecoder jwtDecoder = this.jwtDecoderFactory.createDecoder(dPoPProofContext);
    assertThatExceptionOfType(BadJwtException.class).isThrownBy(() -> jwtDecoder.decode(dPoPProofContext.getDPoPProof())).withMessageContaining("JOSE header typ (type) invalid-type not allowed");
}

