    BearerTokenAuthentication factorOne = new BearerTokenAuthentication(TestOAuth2AuthenticatedPrincipals.active(), this.token, AuthorityUtils.createAuthorityList("FACTOR_ONE"));
    BearerTokenAuthentication factorTwo = new BearerTokenAuthentication(TestOAuth2AuthenticatedPrincipals.active((m) -> m.put("k", "v")), new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER, "nekot", Instant.now(), Instant.now().plusSeconds(3600)), AuthorityUtils.createAuthorityList("FACTOR_TWO"));
