    Map<Saml2AuthenticatedPrincipal, Integer> valuesByPrincipal = new LinkedHashMap<>();
    DefaultSaml2AuthenticatedPrincipal principal = new DefaultSaml2AuthenticatedPrincipal("user", Map.of());
    valuesByPrincipal.put(principal, 1);
    principal = new DefaultSaml2AuthenticatedPrincipal("user", Map.of());
    assertThat(valuesByPrincipal.get(principal)).isEqualTo(1);
    principal = new DefaultSaml2AuthenticatedPrincipal("user", Map.of());
    principal.setRelyingPartyRegistrationId("id");
    assertThat(valuesByPrincipal.get(principal)).isNull();
    valuesByPrincipal.put(principal, 2);
    principal = new DefaultSaml2AuthenticatedPrincipal("user", Map.of());
    principal.setRelyingPartyRegistrationId("id");
    assertThat(valuesByPrincipal.get(principal)).isEqualTo(2);
    principal = new DefaultSaml2AuthenticatedPrincipal("USER", Map.of());
    principal.setRelyingPartyRegistrationId("id");
    assertThat(valuesByPrincipal.get(principal)).isNull();
}

@Test
void toBuilderWhenApplyThenCopies() {
    Saml2ResponseAssertion.Builder prototype = Saml2ResponseAssertion.withResponseValue("response");
    Saml2AssertionAuthentication factorOne = new Saml2AssertionAuthentication("alice", prototype.nameId("alice").build(), AuthorityUtils.createAuthorityList("FACTOR_ONE"), "alice");
    Saml2AssertionAuthentication factorTwo = new Saml2AssertionAuthentication("bob", prototype.nameId("bob").build(), AuthorityUtils.createAuthorityList("FACTOR_TWO"), "bob");
    Saml2AssertionAuthentication result = factorOne.toBuilder().authorities((a) -> a.addAll(factorTwo.getAuthorities())).principal(factorTwo.getPrincipal()).credentials(factorTwo.getCredentials()).relyingPartyRegistrationId(factorTwo.getRelyingPartyRegistrationId()).build();
    Set<String> authorities = AuthorityUtils.authorityListToSet(result.getAuthorities());
    assertThat(result.getPrincipal()).isSameAs(factorTwo.getPrincipal());
    assertThat(result.getCredentials()).isSameAs(factorTwo.getCredentials());
    assertThat(result.getRelyingPartyRegistrationId()).isSameAs(factorTwo.getRelyingPartyRegistrationId());
    assertThat(authorities).containsExactlyInAnyOrder("FACTOR_ONE", "FACTOR_TWO");
}

