@Test
public void buildPreservesCredentialsOrder() {
    Saml2X509Credential altRpCredential = TestSaml2X509Credentials.altPrivateCredential();
    Saml2X509Credential altApCredential = TestSaml2X509Credentials.altPublicCredential();
    Saml2X509Credential verifyingCredential = TestSaml2X509Credentials.relyingPartyVerifyingCredential();
    Saml2X509Credential encryptingCredential = TestSaml2X509Credentials.relyingPartyEncryptingCredential();
    Saml2X509Credential signingCredential = TestSaml2X509Credentials.relyingPartySigningCredential();
    Saml2X509Credential decryptionCredential = TestSaml2X509Credentials.relyingPartyDecryptingCredential();
    // Test with the alt credentials first
    RelyingPartyRegistration relyingPartyRegistration = TestRelyingPartyRegistrations.noCredentials().assertingPartyMetadata((assertingParty) -> assertingParty.verificationX509Credentials((c) -> {
        c.add(altApCredential);
        c.add(verifyingCredential);
    }).encryptionX509Credentials((c) -> {
        c.add(altApCredential);
        c.add(encryptingCredential);
    })).signingX509Credentials((c) -> {
        c.add(altRpCredential);
        c.add(signingCredential);
    }).decryptionX509Credentials((c) -> {
        c.add(altRpCredential);
        c.add(decryptionCredential);
    }).build();
    assertThat(relyingPartyRegistration.getSigningX509Credentials()).containsExactly(altRpCredential, signingCredential);
    assertThat(relyingPartyRegistration.getDecryptionX509Credentials()).containsExactly(altRpCredential, decryptionCredential);
    assertThat(relyingPartyRegistration.getAssertingPartyMetadata().getVerificationX509Credentials()).containsExactly(altApCredential, verifyingCredential);
    assertThat(relyingPartyRegistration.getAssertingPartyMetadata().getEncryptionX509Credentials()).containsExactly(altApCredential, encryptingCredential);
    // Test with the alt credentials last
    relyingPartyRegistration = TestRelyingPartyRegistrations.noCredentials().assertingPartyMetadata((assertingParty) -> assertingParty.verificationX509Credentials((c) -> {
        c.add(verifyingCredential);
        c.add(altApCredential);
    }).encryptionX509Credentials((c) -> {
        c.add(encryptingCredential);
        c.add(altApCredential);
    })).signingX509Credentials((c) -> {
        c.add(signingCredential);
        c.add(altRpCredential);
    }).decryptionX509Credentials((c) -> {
        c.add(decryptionCredential);
        c.add(altRpCredential);
    }).build();
    assertThat(relyingPartyRegistration.getSigningX509Credentials()).containsExactly(signingCredential, altRpCredential);
    assertThat(relyingPartyRegistration.getDecryptionX509Credentials()).containsExactly(decryptionCredential, altRpCredential);
    assertThat(relyingPartyRegistration.getAssertingPartyMetadata().getVerificationX509Credentials()).containsExactly(verifyingCredential, altApCredential);
    assertThat(relyingPartyRegistration.getAssertingPartyMetadata().getEncryptionX509Credentials()).containsExactly(encryptingCredential, altApCredential);
}

