@Test
public void toBuilderWhenApplyThenCopies() {
    PreAuthenticatedAuthenticationToken factorOne = new PreAuthenticatedAuthenticationToken("alice", "pass", AuthorityUtils.createAuthorityList("FACTOR_ONE"));
    PreAuthenticatedAuthenticationToken factorTwo = new PreAuthenticatedAuthenticationToken("bob", "ssap", AuthorityUtils.createAuthorityList("FACTOR_TWO"));
    PreAuthenticatedAuthenticationToken result = factorOne.toBuilder().authorities((a) -> a.addAll(factorTwo.getAuthorities())).principal(factorTwo.getPrincipal()).credentials(factorTwo.getCredentials()).build();
    Set<String> authorities = AuthorityUtils.authorityListToSet(result.getAuthorities());
    assertThat(result.getPrincipal()).isSameAs(factorTwo.getPrincipal());
    assertThat(result.getCredentials()).isSameAs(factorTwo.getCredentials());
    assertThat(authorities).containsExactlyInAnyOrder("FACTOR_ONE", "FACTOR_TWO");
}

