public void getFirewalledRequestWhenLowercaseEncodedPathThenException() {
    this.request.setRequestURI("/context-root/a/b;%2f1/c");
    this.request.setContextPath("/context-root");
    this.request.setServletPath("");
    // URL decoded requestURI
    this.request.setPathInfo("/a/b;/1/c");
    assertThatExceptionOfType(RequestRejectedException.class).isThrownBy(() -> this.firewall.getFirewalledRequest(this.request));
}

