@Test
void createPublicKeyCredentialCreationOptionsWhenDefaultsThenSuccess() {
    PublicKeyCredentialCreationOptions expectedCreationOptions = TestPublicKeyCredentialCreationOptions.createPublicKeyCredentialCreationOptions().rp(this.rpEntity).user(TestPublicKeyCredentialUserEntities.userEntity().build()).build();
    PublicKeyCredentialCreationOptions creationOptions = this.rpOperations.createPublicKeyCredentialCreationOptions(new ImmutablePublicKeyCredentialCreationOptionsRequest(this.user));
    assertThat(creationOptions).usingRecursiveComparison().ignoringFields("challenge", "user.id").isEqualTo(expectedCreationOptions);
    // https://www.w3.org/TR/webauthn-3/#dom-publickeycredentialcreationoptions-rp
    assertThat(creationOptions.getRp()).isNotNull();
    assertThat(creationOptions.getRp().getName()).describedAs("Its value's name member is REQUIRED").isNotNull();
    // https://www.w3.org/TR/webauthn-3/#dom-publickeycredentialcreationoptions-user
    PublicKeyCredentialUserEntity userEntity = creationOptions.getUser();
    assertThat(userEntity).isNotNull();
    assertThat(userEntity.getName()).isNotNull();
    assertThat(userEntity.getDisplayName()).isNotNull();
    // https://www.w3.org/TR/webauthn-3/#dom-publickeycredentialuserentity-id
    Bytes userId = userEntity.getId();
    assertThat(userId).isNotNull();
    assertThat(userId.getBytes()).describedAs("user id is a maximum size of 64 bytes").hasSizeLessThanOrEqualTo(64);
    assertThat(userId.getBytes()).describedAs("we want enough entropy in the user id, so it should be at least 16 bytes").hasSizeGreaterThanOrEqualTo(16);
    Bytes challenge = creationOptions.getChallenge();
    assertThat(challenge).isNotNull();
    byte[] challengeBytes = challenge.getBytes();
    // https://www.w3.org/TR/webauthn-3/#sctn-cryptographic-challenges
    assertThat(challengeBytes).describedAs("Challenges should be at least 16 bytes").hasSizeGreaterThanOrEqualTo(16);
    // https://www.w3.org/TR/webauthn-3/#dom-publickeycredentialcreationoptions-pubkeycredparams
    assertThat(creationOptions.getPubKeyCredParams()).describedAs("Relying Parties that wish to support a wide range of authenticators SHOULD include at least the following COSEAlgorithmIdentifier values").containsExactly(PublicKeyCredentialParameters.EdDSA, PublicKeyCredentialParameters.ES256, PublicKeyCredentialParameters.RS256);
}

