    PublicKeyCredential publicKey = TestPublicKeyCredentials.createPublicKeyCredential(responseBldr.build()).build();
    ImmutableRelyingPartyRegistrationRequest registrationRequest = new ImmutableRelyingPartyRegistrationRequest(options, new RelyingPartyPublicKey(publicKey, this.label));
    assertThatRuntimeException().isThrownBy(() -> this.rpOperations.registerCredential(registrationRequest)).withMessageContaining("ClientData.type");
}

